instructions.syntax:
TT_CFGSHIFTMASK(/* u1 */ MaskMode,
                /* u3 */ AluMode,
                /* u5 */ MaskWidth,
                /* u5 */ RotateAmt,
                /* u2 */ ScratchIndex,
                /* u8 */ CfgIndex)

TT_CLEARDVALID(((/* bool */ FlipSrcB) << 1) +
                 /* bool */ FlipSrcA,
               ((/* bool */ KeepReadingSameSrc) << 1) +
                 /* bool */ Reset);

TT_ELWADD(((/* bool */ FlipSrcB) << 1) +
            /* bool */ FlipSrcA,
            /* bool */ AddDst,
          ((/* bool */ BroadcastSrcBRow) << 1) +
            /* bool */ BroadcastSrcBCol0,
            /* u2 */ AddrMod,
            /* u10 */ DstRow)

TT_ELWMUL(((/* bool */ FlipSrcB) << 1) +
            /* bool */ FlipSrcA,
            false,
          ((/* bool */ BroadcastSrcBRow) << 1) +
            /* bool */ BroadcastSrcBCol0,
            /* u2 */ AddrMod,
            /* u10 */ DstRow)

TT_ELWSUB(((/* bool */ FlipSrcB) << 1) +
            /* bool */ FlipSrcA,
            /* bool */ AddDst,
          ((/* bool */ BroadcastSrcBRow) << 1) +
            /* bool */ BroadcastSrcBCol0,
            /* u2 */ AddrMod,
            /* u10 */ DstRow)

TT_GAPOOL(((/* bool */ FlipSrcB) << 1) +
            /* bool */ FlipSrcA,
            0,
            /* u2 */ AddrMod,
            false,
            /* u10 */ DstRow)

TT_GMPOOL(((/* bool */ FlipSrcB) << 1) +
            /* bool */ FlipSrcA,
            true,
            /* u2 */ AddrMod,
            /* bool */ ArgMax,
            /* u10 */ DstRow)

TT_INCRWC(((/* bool */ DstCr) << 2) +
          ((/* bool */ SrcBCr) << 1) +
            /* bool */ SrcACr,
            /* u4 */ DstInc,
            /* u4 */ SrcBInc,
            /* u4 */ SrcAInc);

TT_MOVA2D(/* bool */ UseDst32bLo,
          /* u6 */ SrcRow,
          /* u2 */ AddrMod,
         (/* bool */ Move8Rows) << 1,
          /* u10 */ DstRow)

TT_MOVB2A(/* u6 */ SrcARow,
          /* u2 */ AddrMod,
         (/* bool */ Move4Rows) << 1,
          /* u6 */ SrcBRow)

TT_MOVB2D(/* bool */ UseDst32bLo,
          /* u6 */ SrcRow,
          /* u2 */ AddrMod,
        ((/* bool */ Move4Rows) << 2) +
        ((/* bool */ Broadcast1RowTo8) << 1) +
          /* bool */ BroadcastCol0,
          /* u10 */ DstRow)

TT_MOVD2A(/* bool */ UseDst32bLo,
          /* u6 */ SrcRow,
          /* u2 */ AddrMod,
         (/* bool */ Move4Rows) << 1,
          /* u10 */ DstRow)

TT_MOVD2B(/* bool */ UseDst32bLo,
          /* u6 */ SrcRow,
          /* u2 */ AddrMod,
         (/* bool */ Move4Rows) << 1,
          /* u10 */ DstRow)

TT_MVMUL(((/* bool */ FlipSrcB) << 1) +
           /* bool */ FlipSrcA,
           /* bool */ BroadcastSrcBRow,
           /* u2 */ AddrMod,
           /* u10 */ DstRow)

TT_PACR(/* u2 */ AddrMod, /* bool */ ZeroWrite, /* u4 */ PackerMask,
        /* bool */ OvrdThreadId, /* bool */ Concat, /* bool */ Flush,
        /* bool */ Last)

TT_SETADC(((/* bool */ PK) << 2) +
          ((/* bool */ U1) << 1) +
            /* bool */ U0,
            /* u1 */ Channel,
            /* u2 */ XYZW,
            /* u18 */ NewValue)

TT_SETADCXX(((/* bool */ PK) << 2) +
            ((/* bool */ U1) << 1) +
              /* bool */ U0,
              /* u10 */ X1Val,
              /* u10 */ X0Val)

TT_SETRWC(((/* bool */ FlipSrcB) << 1) +
            /* bool */ FlipSrcA,
          ((/* bool */ DstCtoCr) << 3) +
          ((/* bool */ DstCr) << 2) +
          ((/* bool */ SrcBCr) << 1) +
            /* bool */ SrcACr,
            /* u4 */ DstVal,
            /* u4 */ SrcBVal,
            /* u4 */ SrcAVal,
          ((/* bool */ Fidelity) << 3) +
          ((/* bool */ Dst) << 2) +
          ((/* bool */ SrcB) << 1) +
            /* bool */ SrcA);

TT_SFPLOADMACRO(((/* u2 */ MacroIndex) << 2) +
                  /* u2 */ VDLo,
                  /* u4 */ Mod0,
                  /* u3 */ AddrMod,
                ((/* u9 */ Imm9) << 1) +
                  /* u1 */ VDHi)

TT_OP_UNPACR(/* u1 */ WhichUnpacker,
           ((/* u2 */ Ch1YInc) << 6) +
           ((/* u2 */ Ch1ZInc) << 4) +
           ((/* u2 */ Ch0YInc) << 2) +
             /* u2 */ Ch0ZInc,
             false,
             /* u3 */ ContextNumber,
             /* u2 */ ContextADC,
             /* bool */ MultiContextMode,
             /* bool */ FlipSrc,
             false,
             /* bool */ AllDatumsAreZero,
             /* bool */ UseContextCounter,
             /* bool */ RowSearch,
             false,
             false)

TT_ZEROACC(((/* bool */ UseDst32b) << 2) +
             /* u2 */ Mode,
             /* u2 */ AddrMod,
             /* u10 */ Imm10)

TT_ZEROSRC(/* bool */ NegativeInfSrcA,
           /* bool */ SingleBankMatrixUnit,
           /* bool */ BothBanks,
         ((/* bool */ ClearSrcB) << 1) +
           /* bool */ ClearSrcA)
